 CREATE TEMPORARY TABLE rrc277_recipes LIKE tradeskill_recipe;
 CREATE TEMPORARY TABLE rrc277_entries LIKE tradeskill_recipe_entries;
 CREATE TEMPORARY TABLE rrc277_items(id INT PRIMARY KEY,name VARCHAR(64) NOT NULL) ENGINE=InnoDB;
 CREATE TEMPORARY TABLE rrc277_peer_recipes LIKE tradeskill_recipe;
